import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.iKZ1V-y0.js";const d=JSON.parse('{"title":"Binary Flow Stabilizer","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"二进制稳流器","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XZVY2YJV9J2aDl6ik1qPtM","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-XZVY2YJV9J2aDl6ik1qPtM.md","filePath":"logistics/src/page-XZVY2YJV9J2aDl6ik1qPtM.md","lastUpdated":null}'),o={name:"logistics/src/page-XZVY2YJV9J2aDl6ik1qPtM.md"};function n(l,e,s,p,c,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="二进制稳流器" aria-hidden="true"></span><h1 id="binary-flow-stabilizer" tabindex="-1">Binary Flow Stabilizer <a class="header-anchor" href="#binary-flow-stabilizer" aria-label="Permalink to &quot;Binary Flow Stabilizer&quot;">​</a></h1><blockquote><p>Source page ID: <code>XZVY2YJV9J2aDl6ik1qPtM</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XZVY2YJV9J2aDl6ik1qPtM" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>For details, see <a href="./page-zmwxaYgt5aotQWWadn9BqP">Proof of the Minimum Configured Power for Binary-Flow-Stabilizer Power Control</a>.</p><p>Structure: 24/25 rate limiting + uniform binary splitting + three-way splitting.</p><p>The <a href="./page-LbIb8qSMuIb0YhWSlQiP1F">Error Propagation in Serial Structures</a> gives this structure&#39;s theoretical maximum error. The <a href="./page-NrUI311gHlBZnqCa1y780J">Calculating the Range of Stored Energy</a> then gives its maximum energy range, determining whether outages can occur.</p><p>Advantages: calculable energy range, precise power control without waste, controllable structure, simple design.</p><p>Disadvantages: large footprint, cumbersome calculations, generation fixed by structure rather than automatically variable.</p><p>Common constructions for each part:</p><p><strong>24/25 rate limiting</strong></p><p><a href="./page-zV1c50L6fzQlPin20eYPSO">Applications of Some Theories</a></p><p>Output-lag (“4n, 1 s stall”) implementation, error (n-1)/4n=(3-1)/4*3=1/6.</p><p><strong>Uniform binary</strong></p><p><a href="./page-Ot47MftTjTTldcTauMOykC">Uniform Binary</a>, error <a href="./page-MaVX8KkK08q5s2fvVTX5wg">Theoretical Lower Bound for Perfect Uniformity</a>.</p><p>Quick calculation: 3200<em>40</em>0.5<em>24/25</em>p*1/3=x; uniform-binary ratio p=remaining demand/generation x/(5x2^12).</p><p><strong>Three-way splitting</strong></p><p>A three-output splitter divides into three, with error 0.</p><p>Using 24/25 output lag, the device has error M_dev &lt; 6(K-2)/(K-1); conjecturally the error should be &lt;1.</p><p>Translation note: The source&#39;s arithmetic notation, including (3-1)/4*3=1/6 and the quick-calculation expression, is retained without silently resolving its ambiguity.</p></div>',1)])])}const h=t(o,[["render",n]]);export{d as __pageData,h as default};
